[{"id": "C6zzEgraSeb43RPQEnzUQcX5Rodcdgqx", "function": {"index": 0, "name": "write_file", "arguments": {"path": "config_reader.py", "content": "def read_settings(text):
    """
    Parse configuration text, return dict with required keys.
    Raises ValueError on malformed, duplicate, missing, or unknown keys.
    """
    lines = text.splitlines()
    seen_keys = set()
    values = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Malformed line: {line}")
        key, val = stripped.split('=', 1)
        key = key.strip()
        val = val.strip()
        if not key:
            raise ValueError(f"Empty key on line: {line}")
        if key in seen_keys:
            raise ValueError(f"Duplicate key: {key}")
        seen_keys.add(key)
        if key not in ("endpoint", "enabled"):
            raise ValueError(f"Unknown key: {key}")
        # Convert value
        if key == "enabled":
            if val.lower() not in ("true", "false"):
                raise ValueError(f"Invalid value for enabled: {val}")
            enabled = (val.lower() == "true")
            values[key] = enabled
        else:  # endpoint
            if val == "":
                raise ValueError(f"Missing value for endpoint: {key}")
            values[key] = val
    # Ensure required keys present
    required = {"endpoint", "enabled"}
    if seen_keys != required:
        raise ValueError(f"Missing required keys: {required - seen_keys}")
    return values
